/**
 * Indian listed-equity universe.
 *
 * Source of truth: src/lib/stock-universe.json, generated by
 * scripts/sync-stock-universe.mjs from the official NSE / BSE securities
 * masters and keyed on ISIN. Do not hand-edit this data; run `npm run sync:stocks`.
 *
 * One record per company. A company listed on both exchanges appears once and
 * carries both its NSE symbol and BSE scrip code.
 */
import universe from "./stock-universe.json";

export type McapType = "large" | "mid" | "small" | "sme";

export interface StockEntry {
  name: string;
  /** Quote ticker: `SYMBOL.NS` when NSE-listed, otherwise `SCRIPCODE.BO`. */
  ticker: string;
  /** Official NSE industry, a verified curated sector, or "Unclassified". Never guessed. */
  sector: string;
  /** From NSE index membership (or verified curated); undefined when unknown. */
  mcapType?: McapType;
  isin?: string;
  nseSymbol?: string;
  bseCode?: string;
  bseId?: string;
  exchanges?: ("NSE" | "BSE")[];
  /** NSE series (EQ, BE, BZ, SM, ST, ...) */
  series?: string;
  bseGroup?: string;
  board?: "main" | "sme";
  /** Trade-for-trade / non-compliance segment per exchange series or group. */
  restricted?: boolean;
  sectorSource?: "curated" | "nse-industry";
}

interface UniverseRow {
  i: string | null; n: string; s?: string; r?: string; c?: string; d?: string; g?: string;
  b: "M" | "S"; x?: string; k?: "L" | "M" | "S" | "U"; y?: string; z?: "curated" | "nse-industry";
}
interface UniverseFile {
  meta: { generatedAt: string; counts: Record<string, number | Record<string, number>>; sources: Record<string, { fileDate: string; rows: number }> };
  stocks: UniverseRow[];
}

const CAP: Record<string, McapType> = { L: "large", M: "mid", S: "small", U: "sme" };
const RESTRICTED_SERIES = new Set(["BE", "BZ", "SZ"]);
const RESTRICTED_GROUPS = new Set(["T", "TS", "XT", "MT", "MS", "Z", "ZP"]);
export const UNCLASSIFIED = "Unclassified";

export const UNIVERSE_META = (universe as UniverseFile).meta;

export const NSE_STOCKS: StockEntry[] = (universe as UniverseFile).stocks.map((r): StockEntry => {
  const exchanges: ("NSE" | "BSE")[] = [];
  if (r.s) exchanges.push("NSE");
  if (r.c) exchanges.push("BSE");
  const board = r.b === "S" ? "sme" : "main";
  return {
    name: r.n,
    ticker: r.s ? `${r.s}.NS` : `${r.c}.BO`,
    sector: r.y || UNCLASSIFIED,
    mcapType: r.k ? CAP[r.k] : board === "sme" ? "sme" : undefined,
    isin: r.i || undefined,
    nseSymbol: r.s,
    bseCode: r.c,
    bseId: r.d,
    exchanges,
    series: r.r,
    bseGroup: r.g,
    board,
    restricted: (!!r.r && RESTRICTED_SERIES.has(r.r)) || (!!r.g && RESTRICTED_GROUPS.has(r.g.trim())),
    sectorSource: r.z,
  };
});

/** Preferred display order for the sectors the UI has always offered; official industries follow. */
const BASE_SECTORS = [
  "Banking", "IT", "FMCG", "Auto", "Pharma", "Oil & Gas", "Power",
  "Infrastructure", "Metals", "NBFC", "Telecom", "Insurance", "Defense",
  "Chemicals", "Consumer", "Cement", "Tech", "Renewable Energy", "Railways",
  "Real Estate", "Electronics", "Capital Goods", "Healthcare", "Textiles",
  "Logistics", "Media", "Aviation", "Retail", "Fertilizers", "Paints",
  "Sugar", "Paper", "Hospitality", "Education", "Fintech", "EMS", "ETF",
];
const present = new Set(NSE_STOCKS.map(s => s.sector));
export const STOCK_SECTORS: string[] = [
  "All",
  ...BASE_SECTORS.filter(s => present.has(s)),
  ...[...present].filter(s => !BASE_SECTORS.includes(s) && s !== UNCLASSIFIED).sort(),
  ...(present.has(UNCLASSIFIED) ? [UNCLASSIFIED] : []),
];

export const MCAP_FILTERS = ["All", "Large Cap", "Mid Cap", "Small Cap", "SME/Micro"];

/** Key used by the live-price feed: bare NSE symbol, or BSE scrip code for BSE-only stocks. */
export function quoteKey(s: StockEntry): string {
  return s.nseSymbol ?? s.bseCode ?? s.ticker.replace(/\.(NS|BO)$/, "");
}

/** URL-safe identifier for a stock page. NSE symbol when listed there, else BSE scrip code. */
export function stockSlug(s: StockEntry): string {
  return quoteKey(s).toLowerCase().replace(/[^a-z0-9]/g, "-");
}

const norm = (v: string) => v.trim().toLowerCase();
const slugOf = (v: string) => norm(v).replace(/[^a-z0-9]/g, "-");

/** Exact lookup by NSE symbol, BSE scrip code, BSE id, ISIN, full ticker, or slug. Returns undefined if unknown. */
export function findStock(idOrSlug: string): StockEntry | undefined {
  const q = norm(decodeURIComponent(idOrSlug));
  if (!q) return undefined;
  const qs = slugOf(q);
  return (
    NSE_STOCKS.find(s => s.nseSymbol && (norm(s.nseSymbol) === q || slugOf(s.nseSymbol) === qs)) ||
    NSE_STOCKS.find(s => s.bseCode === q) ||
    NSE_STOCKS.find(s => s.isin && norm(s.isin) === q) ||
    NSE_STOCKS.find(s => norm(s.ticker) === q) ||
    NSE_STOCKS.find(s => s.bseId && (norm(s.bseId) === q || slugOf(s.bseId) === qs))
  );
}

export function searchStocks(query: string, limit = 12): StockEntry[] {
  if (!query.trim()) return [];
  const q = norm(query);
  const results: { stock: StockEntry; score: number }[] = [];

  for (const stock of NSE_STOCKS) {
    const name = stock.name.toLowerCase();
    const nse = stock.nseSymbol?.toLowerCase() ?? "";
    const bseId = stock.bseId?.toLowerCase() ?? "";
    const code = stock.bseCode ?? "";
    const isin = stock.isin?.toLowerCase() ?? "";
    const sector = stock.sector.toLowerCase();

    let score = 0;
    if (name === q || nse === q || bseId === q || code === q || isin === q) score = 100;
    else if (name.startsWith(q)) score = 85;
    else if (nse.startsWith(q) || bseId.startsWith(q)) score = 80;
    else if (code.startsWith(q)) score = 70;
    else if (name.includes(q)) score = 50;
    else if (nse.includes(q) || bseId.includes(q)) score = 45;
    else if (sector === q) score = 30;
    else if (sector.includes(q)) score = 20;
    else {
      const words = q.split(/\s+/);
      const matched = words.filter(w => name.includes(w) || nse.includes(w));
      if (matched.length > 0) score = 10 + matched.length * 10;
    }

    if (score > 0) results.push({ stock, score });
  }

  return results.sort((a, b) => b.score - a.score).slice(0, limit).map(r => r.stock);
}

export function getStocksBySector(sector: string): StockEntry[] {
  if (sector === "All") return NSE_STOCKS;
  return NSE_STOCKS.filter(s => s.sector === sector);
}

export function getStocksByMcap(mcapType: string): StockEntry[] {
  if (mcapType === "All") return NSE_STOCKS;
  const map: Record<string, string> = { "Large Cap": "large", "Mid Cap": "mid", "Small Cap": "small", "SME/Micro": "sme" };
  return NSE_STOCKS.filter(s => s.mcapType === map[mcapType]);
}
